-- ₹50 welcome coupon for every existing customer who has already verified their email.
SELECT 'WELCOME-' || translate(upper(substr(md5(random()::text || "users"."id"::text), 1, 6)), '01', 'QZ'), 'fixed', '50.00', '150.00', true, now(), now() + interval '90 days', 'welcome',
  '{"en":"Welcome coupon","hi":"वेलकम कूपन","bn":"ওয়েলকাম কুপন"}'::jsonb, "users"."id", 1, 1, 'signup'
FROM "users"
WHERE "users"."role" = 'customer' AND "users"."email_verified_at" IS NOT NULL AND "users"."deleted_at" IS NULL AND "users"."disabled_at" IS NULL
ON CONFLICT DO NOTHING;
